import { Pipe, PipeTransform } from '@angular/core'; 
import { Tools, Translatory } from 'hwmx-angular/tools';

@Pipe({ name: 'translatory', standalone: false })
export class TranslatoryPipe implements PipeTransform {

    transform(value: string | number | null | undefined, translatory: 'en_US' | 'es_MX' | 'ko-KR' | null = null): string {
        return Tools.IsNotOnlyWhiteSpace(value) ? Translatory.Label(`${value}`, translatory) : '';
    }
}